def to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format="png", bbox_inches="tight")
    buf.seek(0)
    img_b64 = base64.b64encode(buf.read()).decode("utf-8")
    plt.close(fig)
    return img_b64

def main():
    # Load data
    df = pd.read_csv("/app/benchmark/data.csv")
    df['date'] = pd.to_datetime(df['date'])
    df['year'] = df['date'].dt.year
    df['month'] = df['date'].dt.month
    df['day_of_week'] = df['date'].dt.day_name()
    df['is_workout'] = df['workout_type'] != 'None'

    # Compute KPIs
    avg_daily_steps = df['steps'].mean()
    avg_calories = df['calories_burned'].mean()
    avg_sleep = df['sleep_hours'].mean()
    workout_participation = df['is_workout'].mean() * 100
    avg_stress = df['stress_level'].mean()

    # Generate Plots
    plots = {}

    # 1. Demographics
    fig, axes = plt.subplots(1, 2, figsize=(14, 5))
    sns.histplot(data=df, x='age', hue='gender', multiple='stack', ax=axes[0])
    axes[0].set_title('Age Distribution by Gender')
    sns.scatterplot(data=df, x='weight_kg', y='height_cm', hue='gender', alpha=0.5, ax=axes[1])
    axes[1].set_title('Height vs Weight by Gender')
    plots['demographics'] = to_base64(fig)

    # 2. Activity
    fig, axes = plt.subplots(1, 2, figsize=(14, 5))
    sns.countplot(data=df, x='workout_type', order=df['workout_type'].value_counts().index, ax=axes[0])
    axes[0].set_title('Workout Type Distribution')
    axes[0].tick_params(axis='x', rotation=45)
    sns.boxplot(data=df[df['is_workout']], x='workout_type', y='workout_duration_minutes', ax=axes[1])
    axes[1].set_title('Workout Duration by Type')
    axes[1].tick_params(axis='x', rotation=45)
    plots['activity'] = to_base64(fig)

    # 3. Health Vitals
    fig, axes = plt.subplots(1, 2, figsize=(14, 5))
    sns.boxplot(data=df, x='workout_type', y='calories_burned', ax=axes[0])
    axes[0].set_title('Calories Burned by Workout Type')
    axes[0].tick_params(axis='x', rotation=45)
    sns.boxplot(data=df, x='mood', y='sleep_hours', ax=axes[1])
    axes[1].set_title('Sleep Duration by Mood')
