    axes[1].set_title('Mood Distribution')
    plots['lifestyle'] = to_base64(fig)

    # 5. Temporal Trends
    fig, axes = plt.subplots(2, 1, figsize=(14, 10))
    yearly_steps = df.groupby('year')['steps'].mean().reset_index()
    sns.lineplot(data=yearly_steps, x='year', y='steps', marker='o', ax=axes[0])
    axes[0].set_title('Average Daily Steps Year-over-Year')
